constexpr int environments=3072,episode_controls=240,observations=42,critic_observations=43,actions=4;
constexpr int actor_parameters=2564,critic_parameters=2497,minibatch=8192,epochs=2,maximum_updates=32;
constexpr int planned_rows=environments*episode_controls,maximum_actor_steps=5760,maximum_critic_steps=5760;
constexpr uint64_t control_cap=24442480,substep_cap=244424800,gib=1024ull*1024*1024,evidence_cap=8*gib,reserve_bytes=8*gib;
constexpr double seconds_cap=900;constexpr uint32_t version=1;
constexpr uint32_t protocol_magic=0x31505254,checkpoint_magic=0x31435254,batch_magic=0x31425254,ready_magic=0x31595254;
constexpr uint32_t calibration_seed=0x6b514c39u,training_seed=0xd37a8021u,permutation_seed=0x19b6e40du,critic_seed=0x7238af15u;
static_assert(planned_rows%minibatch==0&&maximum_actor_steps==maximum_updates*epochs*(planned_rows/minibatch),"PPO fixed batch/step cap differs");
void require(bool ok,const char* reason){if(!ok)throw std::runtime_error(reason);}
void finite(const std::vector<float>& values){for(float v:values)require(std::isfinite(v),"Nonfinite motor PPO data");}
uint64_t file_hash(const fs::path& path){return grant::whole_file(path);}
void json(const fs::path& path,const std::string& contents){require(!fs::exists(path),"Evidence file already exists");std::ofstream out(path);out<<contents<<'\n';out.close();require(bool(out),"Evidence file write failed");}
struct Stream{cudaStream_t value=nullptr;Stream(){CUDA_CHECK_THROW(cudaStreamCreateWithFlags(&value,cudaStreamNonBlocking));}~Stream(){if(value){cudaStreamSynchronize(value);cudaStreamDestroy(value);}}};
template<class T> std::vector<T> download(const T* ptr,size_t count,cudaStream_t stream){std::vector<T> values(count);if(count)CUDA_CHECK_THROW(cudaMemcpyAsync(values.data(),ptr,count*sizeof(T),cudaMemcpyDeviceToHost,stream));CUDA_CHECK_THROW(cudaStreamSynchronize(stream));return values;}
void sync(cudaStream_t stream){CUDA_CHECK_THROW(cudaGetLastError());CUDA_CHECK_THROW(cudaStreamSynchronize(stream));}
nn::MlpSpec actor_spec(){return {{observations,32,32,actions},{nn::Activation::Tanh,nn::Activation::Tanh,nn::Activation::Identity}};}
nn::MlpSpec critic_spec(){return {{critic_observations,32,32,1},{nn::Activation::Tanh,nn::Activation::Tanh,nn::Activation::Identity}};}
nn::AdamConfig optimizer_config(bool actor){nn::AdamConfig c;c.lr=actor?.0003f:.001f;c.eps=.00001f;c.max_grad_norm=.5f;return c;}
std::vector<float> zero_column42(const std::vector<float>& weights41){require(weights41.size()==2532,"Wrong41-input parent shape");std::vector<float> out(actor_parameters,0);
 for(int r=0;r<32;++r)std::copy_n(weights41.begin()+r*41,41,out.begin()+r*42);std::copy(weights41.begin()+1312,weights41.end(),out.begin()+1344);return out;}
struct Parents{std::vector<float> actor,hold_parameters;float hold_gain=0;uint64_t actor_hash=0,hold_hash=0;};
Parents load_parents(const fs::path& root){Parents out;const auto parent=cp::read((root/"parent-checkpoint.bin").string()),old_protocol=cp::read((root/"parent-protocol.bin").string()),holding=cp::read((root/"holding-parent.bin").string());
 out.actor_hash=cp::checksum(parent);out.hold_hash=cp::checksum(holding);
 require(out.actor_hash==2039539270511780368ull&&cp::checksum(old_protocol)==14874979637633386686ull&&out.hold_hash==16983070322273901339ull,"Frozen parent checksum differs");
 const auto original=rl::read_ppo_training_state(parent,cp::checksum(old_protocol));require(original.actor.update==336&&original.actor.observation_schema==2&&original.actor.reward_version==5,"Wrong canonical336 parent");
 const auto appended=rl::append_zero_input_column(original.actor.parameters);cp::Reader in{holding};require(in.value<uint32_t>()==0x314d4148&&in.value<uint32_t>()==1&&in.value<uint64_t>()!=0&&in.value<uint64_t>()==out.actor_hash,"Wrong holding parent");
 for(uint32_t v:{6u,6u,3u,4u,41u,4u,336u})require(in.value<uint32_t>()==v,"Holding parent contract differs");require(in.value<int>()==7&&in.value<int>()==112&&in.array<float>(2532)==appended,"Qualified holding parent/backbone differs");
 out.hold_parameters=in.array<float>(2);out.hold_gain=in.value<float>();const float sigma=in.value<float>();const auto adam=in.array<uint8_t>();in.finish();require(out.hold_parameters.size()==2&&out.hold_gain>0&&out.hold_gain<1&&sigma>0&&!adam.empty(),"Holding parameter metadata invalid");
 require(out.hold_gain==1.f/(1.f+expf(-out.hold_parameters[0])),"Saved learned holding gain mapping differs");out.actor=zero_column42(appended);return out;}
const auto process_started=std::chrono::steady_clock::now();
struct Budget{uint64_t controls=0,substeps=0,accepted_substeps=0;double prior_seconds=0;std::chrono::steady_clock::time_point started=process_started;
 double seconds()const{return prior_seconds+std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();}
 void guard(uint64_t controls_to_reserve=0,uint64_t steps_to_reserve=0)const{require(controls+controls_to_reserve<=control_cap&&substeps+steps_to_reserve<=substep_cap,"Requested-turn physical budget exhausted");require(seconds()<seconds_cap,"Requested-turn combined native process time exhausted");}
 void add(uint64_t c,uint64_t s,uint64_t a){controls+=c;substeps+=s;accepted_substeps+=a;guard();}
};
void disk_guard(const fs::path& root,int n,bool initial=false){const auto available=fs::space(root).available;const auto batch_bytes=uint64_t(n)*episode_controls*230+uint64_t(n)*(sizeof(m::World)+sizeof(task::Task))*2+4*1024*1024;
 require(available>=reserve_bytes+batch_bytes,"Evidence collection would consume8GiB reserve");if(initial)require(available>=evidence_cap+reserve_bytes,"Requested-turn whole evidence budget plus8GiB reserve does not fit");}
uint64_t protocol_hash(const fs::path& root){return cp::checksum(cp::read((root/"protocol.bin").string()));}
std::vector<uint8_t> protocol_payload(const fs::path& root){cp::Writer w;w.value(protocol_magic);w.value(version);
 for(const char* name:{"approved-protocol.md","parent-checkpoint.bin","parent-protocol.bin","holding-parent.bin"})w.value(file_hash(root/name));
 for(int v:{6,1,5,observations,critic_observations,actions,actor_parameters,critic_parameters,environments,episode_controls,24,minibatch,epochs,maximum_updates,maximum_actor_steps,maximum_critic_steps})w.value(v);
 for(float v:{math::rho,math::log_sigma,1.f,.98f,.2f,.2f,.5f,.0003f,.001f,.5f,.01f})w.value(v);
 for(uint32_t v:{calibration_seed,training_seed,permutation_seed,critic_seed})w.value(v);w.value(control_cap);w.value(substep_cap);w.value(seconds_cap);w.value(evidence_cap);return w.data;}
void validate_protocol(const fs::path& root){require(cp::read((root/"protocol.bin").string())==protocol_payload(root),"Frozen requested-turn protocol differs");(void)load_parents(root);}
struct Counts{uint64_t controls=0,attempted=0,accepted=0;double seconds=0,reward_sum=0;int reason=0,last_substeps=0;bool done=false; p::BodyState before{},candidate{};};
struct Data{
 int n;Stream stream;device_ptr<m::World> worlds,initial_worlds;device_ptr<task::Task> tasks,initial_tasks;device_ptr<Counts> counts;device_ptr<int> fault,active;
 device_ptr<float> obs,previous_obs,previous_raw,history,raw,old_logp,old_value,reward,done,mask,advantage,returns,actor_input,critic_input,trace,sigma;
 device_ptr<double> energy;device_ptr<uint8_t> substeps;
 explicit Data(int count=environments):n(count),worlds(count),initial_worlds(count),tasks(count),initial_tasks(count),counts(count),fault(1),active(1),
 obs(size_t(count)*episode_controls*observations),previous_obs(size_t(count)*episode_controls*observations),previous_raw(size_t(count)*episode_controls*actions),history(size_t(count)*episode_controls),
 raw(size_t(count)*episode_controls*actions),old_logp(size_t(count)*episode_controls),old_value(size_t(count)*episode_controls),reward(size_t(count)*episode_controls),done(size_t(count)*episode_controls),mask(size_t(count)*episode_controls),
 advantage(size_t(count)*episode_controls),returns(size_t(count)*episode_controls),actor_input(size_t(count)*2*observations),critic_input(size_t(count)*critic_observations),trace(size_t(count)*episode_controls*45),sigma(4),energy(size_t(count)*episode_controls*6),substeps(size_t(count)*episode_controls){
 for(auto* value:{&obs,&previous_obs,&previous_raw,&history,&raw,&old_logp,&old_value,&reward,&done,&mask,&advantage,&returns,&trace})CUDA_CHECK_THROW(cudaMemsetAsync(value->get(),0,value->size_bytes(),stream.value));
 CUDA_CHECK_THROW(cudaMemsetAsync(energy.get(),0,energy.size_bytes(),stream.value));CUDA_CHECK_THROW(cudaMemsetAsync(substeps.get(),0,substeps.size_bytes(),stream.value));CUDA_CHECK_THROW(cudaMemsetAsync(fault.get(),0,sizeof(int),stream.value));
 const float s[4]={-1,-1,-1,-1};sigma.copy_from_host(s,4);
 }
};
struct Minibatch{
 device_ptr<float> obs{2*minibatch*observations},critic_obs{minibatch*critic_observations},previous_raw{minibatch*4},history{minibatch},raw{minibatch*4},old_logp{minibatch},old_value{minibatch},advantage{minibatch},returns{minibatch},mask{minibatch},mean_gradient{2*minibatch*4},value_gradient{minibatch},row_stats{minibatch*6},stats{6},adv_stats{3};
};
CUDARL_HD inline void body_values(const p::BodyState& b,float* x){x[0]=b.position.x;x[1]=b.position.y;x[2]=b.position.z;x[3]=b.orientation.x;x[4]=b.orientation.y;x[5]=b.orientation.z;x[6]=b.orientation.w;
 for(int j=0;j<4;++j)x[7+j]=b.angle[j];for(int j=0;j<10;++j)x[11+j]=b.velocity[j];x[21]=b.work;x[22]=b.travel;}
CUDARL_HD inline p::BodyState values_body(const float* x){p::BodyState b;b.position={x[0],x[1],x[2]};b.orientation={x[3],x[4],x[5],x[6]};for(int j=0;j<4;++j)b.angle[j]=x[7+j];for(int j=0;j<10;++j)b.velocity[j]=x[11+j];b.work=x[21];b.travel=x[22];return b;}
__global__ void initialize_episodes(int n,bool evaluation,bool withheld,float angle_cap,m::World* worlds,m::World* initial_worlds,task::Task* tasks,task::Task* initial_tasks,Counts* counts,int* fault){
 const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;const int id=evaluation?(i/11)*12+1+i%11:i%24;counts[i]=Counts{};
 if(!task::initialize(id,worlds[i],tasks[i],angle_cap,withheld))atomicCAS(fault,0,1);initial_worlds[i]=worlds[i];initial_tasks[i]=tasks[i];}
__global__ void inputs(int n,int tick,m::World* worlds,task::Task* tasks,float* obs,float* previous_obs,float* previous_raw,float* history,const float* all_raw,float* combined,float* critic_input,int* fault){
 const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;float* current=obs+(size_t(tick)*n+i)*observations;float* prev=previous_obs+(size_t(tick)*n+i)*observations;
 if(!tasks[i].done&&!*fault){if(!task::update_request(tasks[i],worlds[i])||!task::observe(tasks[i],worlds[i],current))atomicCAS(fault,0,2);}
 for(int j=0;j<observations;++j){prev[j]=tick?obs[(size_t(tick-1)*n+i)*observations+j]:0;combined[i*observations+j]=current[j];combined[(n+i)*observations+j]=prev[j];critic_input[i*critic_observations+j]=current[j];}
 const size_t row=size_t(tick)*n+i;history[row]=tick&&!tasks[i].done?1.f:0.f;for(int j=0;j<4;++j)previous_raw[row*4+j]=tick?all_raw[(size_t(tick-1)*n+i)*4+j]:0;
 critic_input[i*critic_observations+observations]=1.f-float(tick)/episode_controls;
}
__global__ void deterministic_actions(int n,const float* means,const float* previous,const float* prior_raw,const float* history,const float* sigma,float* raw,float* logp){
 const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;for(int j=0;j<4;++j)raw[i*4+j]=means[i*4+j];
 logp[i]=rl::ar_logp(means+i*4,previous+i*4,prior_raw+i*4,sigma,4,math::rho,history[i]!=0,raw+i*4);
}
__global__ void advance_episodes(int n,int tick,float hold_gain,m::World* worlds,task::Task* tasks,Counts* counts,const float* value,
 float* raw,float* logp,float* old_value,float* reward,float* done,float* mask,float* trace,double* energy,uint8_t* substeps,int* fault,int* active,p::BodyState* all_substeps){
 const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n||*fault)return;const size_t row=size_t(tick)*n+i;
 if(tasks[i].done){for(int j=0;j<4;++j)raw[i*4+j]=0;logp[i]=0;return;}
 float* saved=trace+row*45;for(int j=0;j<4;++j){saved[j]=worlds[i].physical.held_targets[j];saved[4+j]=worlds[i].reference_rate[j];saved[8+j]=worlds[i].physical.last_actual_torques[j];saved[35+j]=raw[i*4+j];}
 saved[39]=logp[i];saved[40]=old_value[row]=value[i];mask[row]=1;float command[4];const float gain=tasks[i].holding?hold_gain:1.f;
 for(int j=0;j<4;++j){command[j]=tanhf(gain*raw[i*4+j]);if(!p::finite_number(command[j])||!p::finite_number(raw[i*4+j])){atomicCAS(fault,0,3);return;}}
 ++counts[i].controls;task::StepInfo info;task::step_control(worlds[i],tasks[i],command,info,all_substeps?all_substeps+row*10:nullptr);
 counts[i].attempted+=info.attempted_substeps;counts[i].accepted+=info.accepted_substeps;counts[i].last_substeps=info.accepted_substeps;counts[i].seconds+=info.seconds;
 body_values(worlds[i].physical.body,saved+12);substeps[row]=uint8_t(info.accepted_substeps);for(int j=0;j<6;++j)energy[row*6+j]=info.energy_after[j];saved[42]=info.maximum_depth_m;saved[43]=info.maximum_tilt_deg;saved[44]=info.minimum_clearance_m;
 if(info.hard_fault||!info.valid){counts[i].reason=3;counts[i].before=info.before;counts[i].candidate=info.candidate;atomicCAS(fault,0,4);return;}
 const auto transition=task::record(tasks[i],worlds[i],info);if(!transition.accepted||transition.truncated||!p::finite_number(transition.reward)){atomicCAS(fault,0,5);return;}
 saved[41]=reward[row]=transition.reward;done[row]=transition.done?1.f:0.f;counts[i].reward_sum+=double(transition.reward);counts[i].reason=int(tasks[i].reason);counts[i].done=transition.done;if(!transition.done)atomicAdd(active,1);
}
// Inactive padding is excluded from both GAE and its normalization. Each real
// episode has a true terminal; there is no final-value bootstrap.
__global__ void masked_gae(int n,const float* reward,const float* value,const float* done,const float* mask,float* advantage,float* returns){
 const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;float next_value=0,gae=0;
 for(int t=episode_controls-1;t>=0;--t){const size_t row=size_t(t)*n+i;if(!mask[row]){advantage[row]=returns[row]=0;next_value=gae=0;continue;}
 const float continuation=1.f-done[row];const float delta=reward[row]+continuation*next_value-value[row];gae=delta+continuation*.98f*gae;advantage[row]=gae;returns[row]=gae+value[row];next_value=value[row];}
}
__global__ void active_stats(int n,const float* values,const float* mask,float* stats){if(blockIdx.x||threadIdx.x)return;double sum=0,square=0,count=0;for(int i=0;i<n;++i)if(mask[i]){sum+=values[i];square+=double(values[i])*values[i];++count;}
 const double mean=count?sum/count:0;stats[0]=float(mean);stats[1]=float(sqrt(fmax(0.,count?square/count-mean*mean:0)));stats[2]=float(count);}
__global__ void minibatch_active(int n,const float* mask,float* stats){if(blockIdx.x||threadIdx.x)return;int count=0;for(int i=0;i<n;++i)count+=mask[i]!=0;stats[5]=float(count);}
__global__ void gather_critic(rl::Permutation permutation,int first,int count,int n,const float* observations_all,float* critic_input){const int k=blockIdx.x*blockDim.x+threadIdx.x;if(k>=count*critic_observations)return;const int i=k/critic_observations,j=k%critic_observations;const int row=int(rl::permute(permutation,uint32_t(first+i)));
 critic_input[k]=j<observations?observations_all[size_t(row)*observations+j]:1.f-float(row/n)/episode_controls;}
__global__ void loss_rows(int n,const float* means,const float* values,const float* previous_raw,const float* history,const float* raw,const float* old_logp,const float* old_values,const float* advantage,const float* returns,const float* mask,const float* adv_stats,const float* stats,float* dmean,float* dvalue,float* row_stats){
 const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;for(int j=0;j<4;++j)dmean[i*4+j]=dmean[(n+i)*4+j]=0;dvalue[i]=0;for(int j=0;j<6;++j)row_stats[i*6+j]=0;if(!mask[i]||stats[5]==0)return;
 const auto terms=math::loss(means+i*4,means+(n+i)*4,previous_raw+i*4,history[i]!=0,raw+i*4,old_logp[i],(advantage[i]-adv_stats[0])/(adv_stats[1]+1e-8f),values[i],old_values[i],returns[i],1.f/stats[5],dmean+i*4,dmean+(n+i)*4,dvalue+i);
 row_stats[i*6]=terms.pg_loss;row_stats[i*6+1]=terms.v_loss;row_stats[i*6+2]=terms.entropy;row_stats[i*6+3]=terms.approx_kl;row_stats[i*6+4]=terms.clipped;row_stats[i*6+5]=1;
}
__global__ void finite_array(const float* values,int n,int* fault){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n&&!p::finite_number(values[i]))atomicCAS(fault,0,6);}
struct Collected{int n=0,ticks=0,purpose=0,index=0,fault=0;bool withheld=false;float angle_cap=90;std::vector<float> actor,critic,trace;std::vector<double> energy;std::vector<uint8_t> substeps;std::vector<Counts> counts;std::vector<m::World> initial_worlds,final_worlds;std::vector<task::Task> initial_tasks,final_tasks;std::vector<p::BodyState> five_ms;};
Collected collect(Data& data,nn::GpuMlp& actor,nn::GpuMlp& critic,const Parents& parents,const fs::path& directory,Budget& budget,int purpose,int index,bool sampled,bool withheld=false,float angle_cap=90){
 disk_guard(directory.parent_path(),data.n);require(!fs::exists(directory),"Batch identity already exists");fs::create_directory(directory);budget.guard(uint64_t(data.n)*episode_controls,uint64_t(data.n)*episode_controls*10);
 const auto stream=data.stream.value;const bool evaluation=purpose>=2;device_ptr<p::BodyState> five_ms(evaluation?size_t(data.n)*episode_controls*10:0);if(evaluation)CUDA_CHECK_THROW(cudaMemsetAsync(five_ms.get(),0,five_ms.size_bytes(),stream));
 initialize_episodes<<<(data.n+127)/128,128,0,stream>>>(data.n,evaluation,withheld,angle_cap,data.worlds.get(),data.initial_worlds.get(),data.tasks.get(),data.initial_tasks.get(),data.counts.get(),data.fault.get());sync(stream);
 Collected saved;saved.n=data.n;saved.purpose=purpose;saved.index=index;saved.withheld=withheld;saved.angle_cap=angle_cap;saved.actor=actor.get_params();saved.critic=critic.get_params();
 for(int tick=0;tick<episode_controls;++tick){budget.guard();const size_t row=size_t(tick)*data.n;CUDA_CHECK_THROW(cudaMemsetAsync(data.active.get(),0,sizeof(int),stream));
 inputs<<<(data.n+127)/128,128,0,stream>>>(data.n,tick,data.worlds.get(),data.tasks.get(),data.obs.get(),data.previous_obs.get(),data.previous_raw.get(),data.history.get(),data.raw.get(),data.actor_input.get(),data.critic_input.get(),data.fault.get());
 actor.forward(data.actor_input.get(),data.n*2,stream);critic.forward(data.critic_input.get(),data.n,stream);
 if(sampled)rl::sample_ar_gaussian(actor.output(),data.sigma.get(),data.previous_raw.get()+row*4,data.history.get()+row,data.n,4,math::rho,purpose==0?calibration_seed:training_seed,uint32_t(index*episode_controls+tick),data.raw.get()+row*4,data.old_logp.get()+row,stream);
 else deterministic_actions<<<(data.n+127)/128,128,0,stream>>>(data.n,actor.output(),actor.output()+data.n*4,data.previous_raw.get()+row*4,data.history.get()+row,data.sigma.get(),data.raw.get()+row*4,data.old_logp.get()+row);
 advance_episodes<<<(data.n+63)/64,64,0,stream>>>(data.n,tick,parents.hold_gain,data.worlds.get(),data.tasks.get(),data.counts.get(),critic.output(),data.raw.get()+row*4,data.old_logp.get()+row,data.old_value.get(),data.reward.get(),data.done.get(),data.mask.get(),data.trace.get(),data.energy.get(),data.substeps.get(),data.fault.get(),data.active.get(),evaluation?five_ms.get():nullptr);
 sync(stream);saved.ticks=tick+1;const auto stop=download(data.fault.get(),1,stream);if(stop[0]){saved.fault=stop[0];break;}if(download(data.active.get(),1,stream)[0]==0)break;
 }
 saved.counts=download(data.counts.get(),data.n,stream);uint64_t c=0,s=0,a=0;for(const auto& count:saved.counts){c+=count.controls;s+=count.attempted;a+=count.accepted;}budget.controls+=c;budget.substeps+=s;budget.accepted_substeps+=a;
 const size_t stored_rows=size_t(data.n)*episode_controls;saved.trace=download(data.trace.get(),stored_rows*45,stream);saved.energy=download(data.energy.get(),stored_rows*6,stream);saved.substeps=download(data.substeps.get(),stored_rows,stream);
 saved.initial_worlds=download(data.initial_worlds.get(),data.n,stream);saved.final_worlds=download(data.worlds.get(),data.n,stream);saved.initial_tasks=download(data.initial_tasks.get(),data.n,stream);saved.final_tasks=download(data.tasks.get(),data.n,stream);if(evaluation)saved.five_ms=download(five_ms.get(),stored_rows*10,stream);
 return saved;
}
void write_batch(const fs::path& directory,const Collected& b,uint64_t protocol){
