 std::ostringstream out;out<<"{\"schema\":1,\"n\":"<<b.n<<",\"horizon\":240,\"purpose\":"<<b.purpose<<",\"index\":"<<b.index<<",\"ticks\":"<<b.ticks<<",\"controls\":"<<controls<<",\"attempted_substeps\":"<<attempted<<",\"accepted_substeps\":"<<accepted<<",\"fault\":"<<b.fault<<",\"trace_floats_per_row\":45,\"energy_doubles_per_row\":6,\"flag_bytes_per_row\":2,\"intermediate_evidence\":\""<<(b.five_ms.empty()?"accepted control endpoints plus native extrema of all accepted5ms states":"all accepted5ms BodyState values; six energy ledgers at control endpoints")<<"\"}";json(directory/"collection.json",out.str());
