struct Assessment{int passes=0;std::vector<bool> passed;};
Assessment score_evaluation(const Collected& b,const fs::path& directory){Assessment result;std::ofstream cases(directory/"cases.csv");cases<<"case,pose,offset_deg,controls,reason,passed,late_forward_m_s,late_course_error_deg,late_vector_rmse_m_s,max_depth_m,max_tilt_deg,mean_head_error_deg,head_error_rms_deg,positive_work_j\n";cases<<std::setprecision(17);
 for(int i=0;i<b.n;++i){const auto& context=b.final_tasks[i];const auto heading=context.forward.request.heading;double sumx=0,sumy=0,sumz=0,square=0,sin_head=0,cos_head=0,square_head=0;int count=0;double maximum_depth=b.initial_tasks[i].maximum_depth_m,maximum_tilt=b.initial_tasks[i].maximum_tilt_deg;
 for(int t=0;t<episode_controls;++t){const auto* x=b.trace.data()+(size_t(t)*b.n+i)*45;if(!b.substeps[size_t(t)*b.n+i])continue;maximum_depth=std::max(maximum_depth,double(x[42]));maximum_tilt=std::max(maximum_tilt,double(x[43]));
 if(t>=160){const auto body=values_body(x+12);const auto v=cudarl::motor::motion(body).velocity_m_s;const auto error=v-heading*.008f;sumx+=v.x;sumy+=v.y;sumz+=v.z;square+=p::dot(error,error);
 const auto forward=body.orientation.rotate({1,0,0});const double angle=atan2(double(forward.z)*heading.x-double(forward.x)*heading.z,double(forward.x)*heading.x+double(forward.z)*heading.z);sin_head+=sin(angle);cos_head+=cos(angle);square_head+=angle*angle;++count;}}
 const double vx=count?sumx/count:0,vy=count?sumy/count:0,vz=count?sumz/count:0;const double along=vx*heading.x+vy*heading.y+vz*heading.z;
 const double course=count?fabs(atan2(vz*heading.x-vx*heading.z,vx*heading.x+vz*heading.z))*180/cudarl::movement::pi:180;const double rmse=count?sqrt(square/count):1;
 const bool pass=b.fault==0&&b.counts[i].controls==episode_controls&&b.counts[i].reason==task::Deadline&&count==80&&along>=.006&&course<=5&&rmse<=.0025&&maximum_depth<=.001&&maximum_tilt<=10;
 result.passed.push_back(pass);result.passes+=pass;cases<<i<<','<<context.pose<<','<<context.effective_offset_deg<<','<<b.counts[i].controls<<','<<b.counts[i].reason<<','<<int(pass)<<','<<along<<','<<course<<','<<rmse<<','<<maximum_depth<<','<<maximum_tilt<<','<<(count?atan2(sin_head,cos_head)*180/cudarl::movement::pi:0)<<','<<(count?sqrt(square_head/count)*180/cudarl::movement::pi:0)<<','<<b.final_worlds[i].positive_work<<'\n';}
 cases.close();require(bool(cases),"Assessment CSV write failed");std::ostringstream out;out<<"{\"passes\":"<<result.passes<<",\"cases\":"<<b.n<<",\"all_accepted5ms_body_extrema\":true,\"late_controls\":[161,240],\"head_and_work_report_only\":true,\"checkpoint_selection\":false}";json(directory/"assessment.json",out.str());return result;
}
void save_checkpoint(const fs::path& path,uint64_t protocol,const Parents& parents,int update,nn::GpuMlp& actor,nn::GpuMlp& critic,nn::GpuAdam& actor_opt,nn::GpuAdam& critic_opt){
 require(actor_opt.steps()<=maximum_actor_steps&&critic_opt.steps()<=maximum_critic_steps,"Adam cap exceeded");cp::Writer w;w.value(checkpoint_magic);w.value(version);w.value(protocol);w.value(parents.actor_hash);w.value(parents.hold_hash);
 for(int v:{6,1,5,42,43,4,2564,2497,336,update,actor_opt.steps(),critic_opt.steps()})w.value(v);w.value(parents.hold_gain);w.array(parents.hold_parameters);w.value(math::rho);w.value(math::log_sigma);w.array(actor.get_params());w.array(critic.get_params());actor_opt.save(w);critic_opt.save(w);cp::write_atomic(path.string(),w.data);
}
struct SavedCheckpoint{int update=0,actor_steps=0,critic_steps=0;std::vector<float> actor,critic;std::vector<uint8_t> actor_adam,critic_adam;};
SavedCheckpoint read_checkpoint(const fs::path& path,uint64_t protocol,const Parents& parents){const auto bytes=cp::read(path.string());cp::Reader r{bytes};SavedCheckpoint out;require(r.value<uint32_t>()==checkpoint_magic&&r.value<uint32_t>()==version&&r.value<uint64_t>()==protocol&&r.value<uint64_t>()==parents.actor_hash&&r.value<uint64_t>()==parents.hold_hash,"Requested-turn checkpoint identity differs");
 for(int expected:{6,1,5,42,43,4,2564,2497,336})require(r.value<int>()==expected,"Requested-turn checkpoint contract differs");out.update=r.value<int>();out.actor_steps=r.value<int>();out.critic_steps=r.value<int>();require(out.update>=0&&out.update<=32&&out.actor_steps>=0&&out.actor_steps<=5760&&out.critic_steps>=0&&out.critic_steps<=5760,"Checkpoint counters exceed scope");
 require(r.value<float>()==parents.hold_gain&&r.array<float>(2)==parents.hold_parameters&&r.value<float>()==math::rho&&r.value<float>()==math::log_sigma,"Checkpoint gain/AR contract differs");out.actor=r.array<float>(actor_parameters);out.critic=r.array<float>(critic_parameters);require(out.actor.size()==actor_parameters&&out.critic.size()==critic_parameters,"Checkpoint network shape differs");finite(out.actor);finite(out.critic);
 for(bool is_actor:{true,false}){const auto begin=r.position;const auto config=r.value<nn::AdamConfig>();const int count=r.value<int>();const size_t size=is_actor?actor_parameters:critic_parameters;const auto first=r.array<float>(size),second=r.array<float>(size);
 const auto wanted=optimizer_config(is_actor);require(config.lr==wanted.lr&&config.beta1==wanted.beta1&&config.beta2==wanted.beta2&&config.eps==wanted.eps&&config.max_grad_norm==wanted.max_grad_norm&&count==(is_actor?out.actor_steps:out.critic_steps)&&first.size()==size&&second.size()==size,"Adam state contract differs");finite(first);finite(second);for(float v:second)require(v>=0,"Negative Adam second moment");auto& payload=is_actor?out.actor_adam:out.critic_adam;payload.assign(bytes.begin()+begin,bytes.begin()+r.position);}
 r.finish();return out;}
void restore(const SavedCheckpoint& saved,nn::GpuMlp& actor,nn::GpuMlp& critic,nn::GpuAdam& actor_opt,nn::GpuAdam& critic_opt){actor.set_params(saved.actor);critic.set_params(saved.critic);cp::Reader a{saved.actor_adam},c{saved.critic_adam};actor_opt.load(a);critic_opt.load(c);a.finish();c.finish();require(actor_opt.steps()==saved.actor_steps&&critic_opt.steps()==saved.critic_steps,"Restored counters differ");}
void gather_batch(Data& d,Minibatch& b,rl::Permutation permutation,int first){const auto s=d.stream.value;
 rl::gather_rows(permutation,first,minibatch,42,d.obs.get(),b.obs.get(),s);rl::gather_rows(permutation,first,minibatch,42,d.previous_obs.get(),b.obs.get()+minibatch*42,s);
 for(const auto& pair:{std::pair<const float*,float*>{d.previous_raw.get(),b.previous_raw.get()},{d.raw.get(),b.raw.get()}})rl::gather_rows(permutation,first,minibatch,4,pair.first,pair.second,s);
 for(const auto& pair:{std::pair<const float*,float*>{d.history.get(),b.history.get()},{d.old_logp.get(),b.old_logp.get()},{d.old_value.get(),b.old_value.get()},{d.advantage.get(),b.advantage.get()},{d.returns.get(),b.returns.get()},{d.mask.get(),b.mask.get()}})rl::gather_rows(permutation,first,minibatch,1,pair.first,pair.second,s);
 gather_critic<<<(minibatch*43+127)/128,128,0,s>>>(permutation,first,minibatch,d.n,d.obs.get(),b.critic_obs.get());
}
