int optimize(Data& d,Minibatch& b,nn::GpuMlp& actor,nn::GpuMlp& critic,nn::GpuAdam& actor_opt,nn::GpuAdam& critic_opt,int update,const fs::path& directory,Budget& budget){
 const auto s=d.stream.value;cp::Writer ledger;ledger.value(uint32_t{0x314f5254});ledger.value(version);ledger.value(update);const size_t count_position=ledger.data.size();ledger.value(int{0});int records=0;std::ofstream csv(directory/"optimizer.csv");csv<<"epoch,first,active,actor_step,critic_step,pg_loss,value_loss,kl,clipped\n";csv<<std::setprecision(17);
 for(int epoch=0;epoch<epochs;++epoch){double pooled_kl=0,pooled_count=0;const auto permutation=rl::make_permutation(planned_rows,permutation_seed+uint32_t(update*epochs+epoch));
 for(int first=0;first<planned_rows;first+=minibatch){budget.guard();gather_batch(d,b,permutation,first);CUDA_CHECK_THROW(cudaMemsetAsync(b.stats.get(),0,b.stats.size_bytes(),s));minibatch_active<<<1,1,0,s>>>(minibatch,b.mask.get(),b.stats.get());sync(s);const int active=int(download(b.stats.get()+5,1,s)[0]);
 if(!active){csv<<epoch<<','<<first<<",0,"<<actor_opt.steps()<<','<<critic_opt.steps()<<",0,0,0,0\n";continue;}
 actor.forward(b.obs.get(),minibatch*2,s);critic.forward(b.critic_obs.get(),minibatch,s);loss_rows<<<(minibatch+127)/128,128,0,s>>>(minibatch,actor.output(),critic.output(),b.previous_raw.get(),b.history.get(),b.raw.get(),b.old_logp.get(),b.old_value.get(),b.advantage.get(),b.returns.get(),b.mask.get(),b.adv_stats.get(),b.stats.get(),b.mean_gradient.get(),b.value_gradient.get(),b.row_stats.get());
 CUDA_CHECK_THROW(cudaMemsetAsync(b.stats.get(),0,b.stats.size_bytes(),s));rl::sum_columns(b.row_stats.get(),minibatch,6,b.stats.get(),s);actor.zero_grad(s);critic.zero_grad(s);actor.backward(b.mean_gradient.get(),minibatch*2,nullptr,s);critic.backward(b.value_gradient.get(),minibatch,nullptr,s);
 finite_array<<<(actor_parameters+127)/128,128,0,s>>>(actor.grads(),actor_parameters,d.fault.get());finite_array<<<(critic_parameters+127)/128,128,0,s>>>(critic.grads(),critic_parameters,d.fault.get());sync(s);const auto stats=download(b.stats.get(),6,s);finite(stats);require(download(d.fault.get(),1,s)[0]==0,"Nonfinite gradients before Adam");
 ledger.value(epoch);ledger.value(first);ledger.value(active);ledger.value(permutation);ledger.array(actor.get_params());ledger.array(critic.get_params());ledger.array(actor.get_grads());ledger.array(critic.get_grads());ledger.array(stats);
 actor_opt.step(actor.params(),actor.grads(),s);critic_opt.step(critic.params(),critic.grads(),s);sync(s);const auto a=actor.get_params(),c=critic.get_params();finite(a);finite(c);ledger.array(a);ledger.array(c);actor_opt.save(ledger);critic_opt.save(ledger);++records;
 require(actor_opt.steps()<=maximum_actor_steps&&critic_opt.steps()<=maximum_critic_steps,"Adam cap exceeded");pooled_kl+=stats[3];pooled_count+=stats[5];csv<<epoch<<','<<first<<','<<active<<','<<actor_opt.steps()<<','<<critic_opt.steps()<<','<<stats[0]/active<<','<<stats[1]/active<<','<<stats[3]/active<<','<<stats[4]/active<<'\n';
 }
 if(pooled_count&&pooled_kl/pooled_count>.01)break;
 }
