}
// Artificial arrays exercise the actual large gather, shared-network backward
// and reductions. They never call a physical integration or an Adam step.
__global__ void synthetic_source(int rows,float* obs,float* previous_obs,float* prior_raw,float* history,float* old_values,float* advantage,float* returns,float* mask){
 const int row=blockIdx.x*blockDim.x+threadIdx.x;if(row>=rows)return;for(int j=0;j<42;++j){obs[size_t(row)*42+j]=j==41?(row%13==0?1.f:0.f):.2f*cudarl::rng::normal(0x7138b2a9u,uint32_t(j),uint32_t(row));previous_obs[size_t(row)*42+j]=j==41?0.f:.2f*cudarl::rng::normal(0x7138b2a9u,uint32_t(j+43),uint32_t(row));}
 for(int j=0;j<4;++j)prior_raw[row*4+j]=.2f*cudarl::rng::normal(0x7138b2a9u,101,uint32_t(row*4+j));history[row]=row%17?1.f:0.f;old_values[row]=float(row%11-5)*.1f;advantage[row]=float(row%19-9)*.07f;returns[row]=float(row%23-11)*.1f;mask[row]=row%29?1.f:0.f;
}
__global__ void synthetic_actions(int n,const float* means,const float* previous_raw,const float* history,float* raw,float* old_logp){const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;float mu[4],sigma[4],s[4]={-1,-1,-1,-1};rl::ar_parameters(means+i*4,means+(n+i)*4,previous_raw+i*4,s,4,math::rho,history[i]!=0,mu,sigma);
 for(int j=0;j<4;++j)raw[i*4+j]=mu[j]+expf(sigma[j])*.2f*cudarl::rng::normal(0x7138b2a9u,117,uint32_t(i*4+j));old_logp[i]=rl::gaussian_logp(mu,sigma,raw+i*4,4)+(i%3==0?.27f:i%3==1?-.27f:0.f);}
double finite_difference_math(){double maximum=0;
 for(int fixture=0;fixture<12;++fixture){double current[4]={.1,-.2,.3,-.4},previous[4]={.4,-.3,.2,-.1},prior_raw[4]={.15,-.2,.1,.3},raw[4]={.2,-.1,.4,.05},sigma[4]={-1,-1,-1,-1},dc[4],dp[4],dv=0;
 const bool history=fixture%2!=0;const double oldp=rl::ar_logp(current,previous,prior_raw,sigma,4,double(math::rho),history,raw)+(fixture%3==0?.27:fixture%3==1?-.27:0);const double adv=fixture%2?.7:-.4,value=fixture%3==0?.6:fixture%3==1?-.3:.05,old=.1,target=fixture%3==0?.8:fixture%3==1?-.7:.4;
 auto objective=[&](){double a[4],b[4],c;const auto t=math::loss(current,previous,prior_raw,history,raw,oldp,adv,value,old,target,1.,a,b,&c);return t.pg_loss+double(math::value_coefficient)*t.v_loss;};
 (void)math::loss(current,previous,prior_raw,history,raw,oldp,adv,value,old,target,1.,dc,dp,&dv);
 for(int j=0;j<9;++j){double* variable=j<4?current+j:j<8?previous+j-4:nullptr;double derivative=0;const double epsilon=1e-6;
 if(variable){const double saved=*variable;*variable=saved+epsilon;const double plus=objective();*variable=saved-epsilon;const double minus=objective();*variable=saved;derivative=(plus-minus)/(2*epsilon);maximum=std::max(maximum,fabs(derivative-(j<4?dc[j]:dp[j-4])));}
 else{double a,b;const double plus=math::value_loss(value+epsilon,old,target,1.,&a),minus=math::value_loss(value-epsilon,old,target,1.,&b);derivative=double(math::value_coefficient)*(plus-minus)/(2*epsilon);maximum=std::max(maximum,fabs(derivative-dv));}}
 }
 return maximum;
}
