 const auto means=download(actor.output(),2*minibatch*4,stream),values=download(critic.output(),minibatch,stream),prior=download(b.previous_raw.get(),minibatch*4,stream),history=download(b.history.get(),minibatch,stream),raw=download(b.raw.get(),minibatch*4,stream),oldp=download(b.old_logp.get(),minibatch,stream),oldv=download(b.old_value.get(),minibatch,stream),adv=download(b.advantage.get(),minibatch,stream),returns=download(b.returns.get(),minibatch,stream),mask=download(b.mask.get(),minibatch,stream),advstats=download(b.adv_stats.get(),3,stream),stats=download(b.stats.get(),6,stream),gradient=download(b.mean_gradient.get(),2*minibatch*4,stream),vgradient=download(b.value_gradient.get(),minibatch,stream),rowstats=download(b.row_stats.get(),minibatch*6,stream);
