 cp::Writer w;w.value(uint32_t{0x315a5254});w.value(version);w.value(protocol_hash(root));w.value(fixture);w.value(permutation);w.array(indices);w.array(parents.actor);w.array(critic.get_params());w.array(download(b.obs.get(),2*minibatch*42,stream));w.array(download(b.critic_obs.get(),minibatch*43,stream));
 for(const auto* array:{&means,&values,&prior,&history,&raw,&oldp,&oldv,&adv,&returns,&mask,&advstats,&gradient,&vgradient,&rowstats,&stats})w.array(*array);w.array(actor.get_grads());w.array(critic.get_grads());cp::write_atomic((root/("pure-bulk-"+std::to_string(fixture)+".bin")).string(),w.data);
 for(int i=0;i<minibatch;++i){double now[4],prev[4],pa[4],a[4],dc[4]{},dp[4]{},dv=0;for(int j=0;j<4;++j){now[j]=means[i*4+j];prev[j]=means[(minibatch+i)*4+j];pa[j]=prior[i*4+j];a[j]=raw[i*4+j];}
