void network_gradient_zero(const fs::path& root,const Parents& parents){constexpr int n=16;std::vector<double> input(n*2*42),critic_input(n*43),raw(n*4),prior(n*4),history(n),oldp(n),oldvalue(n),adv(n),returns(n);const auto initial_critic=nn::orthogonal_params(critic_spec(),critic_seed,{1.414213562f,1.414213562f,1.f});nn::CpuMlp<double> actor(actor_spec()),critic(critic_spec());actor.params().assign(parents.actor.begin(),parents.actor.end());critic.params().assign(initial_critic.begin(),initial_critic.end());
 for(int i=0;i<n;++i){for(int j=0;j<42;++j){input[i*42+j]=j==41?double(i%2):.15*cudarl::rng::normal(0x7138b2a9u,uint32_t(j),uint32_t(i));input[(n+i)*42+j]=j==41?0:.15*cudarl::rng::normal(0x7138b2a9u,uint32_t(j+43),uint32_t(i));critic_input[i*43+j]=input[i*42+j];}critic_input[i*43+42]=1.-double(i)/n;for(int j=0;j<4;++j){prior[i*4+j]=.1*cudarl::rng::normal(0x7138b2a9u,103,uint32_t(i*4+j));raw[i*4+j]=.1*cudarl::rng::normal(0x7138b2a9u,107,uint32_t(i*4+j));}history[i]=i%3!=0;adv[i]=i%2?.4:-.6;oldvalue[i]=.1;returns[i]=i%2?.2:-.2;}
 actor.forward(input.data(),2*n);critic.forward(critic_input.data(),n);const double sigma[4]={-1,-1,-1,-1};for(int i=0;i<n;++i)oldp[i]=rl::ar_logp(actor.output()+i*4,actor.output()+(n+i)*4,prior.data()+i*4,sigma,4,double(math::rho),history[i]!=0,raw.data()+i*4);
 auto objective=[&](bool gradients){actor.forward(input.data(),2*n);critic.forward(critic_input.data(),n);std::vector<double> da(n*2*4),dv(n);double loss=0;
 for(int i=0;i<n;++i){const auto t=math::loss(actor.output()+i*4,actor.output()+(n+i)*4,prior.data()+i*4,history[i]!=0,raw.data()+i*4,oldp[i],adv[i],critic.output()[i],oldvalue[i],returns[i],1./n,da.data()+i*4,da.data()+(n+i)*4,dv.data()+i);loss+=(t.pg_loss+math::value_coefficient*t.v_loss)/n;}
