void gae_zero(const fs::path& root){constexpr int n=8;const size_t rows=size_t(n)*episode_controls;std::vector<float> rewards(rows),values(rows),dones(rows),mask(rows),zeros(rows),last(n),expected_adv(rows),expected_ret(rows);for(int i=0;i<n;++i){const int length=i==0?240:i*29;
