int baseline(const fs::path& root){validate_protocol(root);grant::require_approved(root,protocol_hash(root));require(!fs::exists(root/"baseline-started"),"Baseline already started; no retry");Budget budget=validate_gate(root);fs::create_directory(root/"baseline-started");cp::Lease lease((root/"physical-owner").string());const auto parents=load_parents(root);const auto initial=read_checkpoint(root/"policy-update-0.bin",protocol_hash(root),parents);Retention retained;
 try{retained=assess_retention(initial.actor,root/"baseline-started/retention",budget,false,parents.hold_gain);require(retention_passed(retained,false),"Inherited old skills failed baseline");disk_guard(root,22);Data data(22);nn::GpuMlp actor(actor_spec(),44,1),critic(critic_spec(),22,critic_seed);initialize_networks(initial,actor,critic);auto b=collect(data,actor,critic,parents,root/"baseline-started/turns",budget,2,0,false);write_batch(root/"baseline-started/turns",b,protocol_hash(root));require(b.fault==0,"Baseline physical/numerical fault");const auto assessment=score_evaluation(b,root/"baseline-started/turns");evidence_guard(root);write_budget(root/"baseline-started/budget.bin",budget,protocol_hash(root));json(root/"baseline-result.json",result_json("baseline",budget,0,0,0,assessment.passes,0,retained,false));return 0;}
 catch(const std::exception& error){write_budget(root/"baseline-started/budget.bin",budget,protocol_hash(root));if(!fs::exists(root/"baseline-result.json"))json(root/"baseline-result.json",result_json("baseline-stopped",budget,0,0,0,0,0,retained,false));std::cerr<<error.what()<<'\n';return 2;}}
int calibrate(const fs::path& root){validate_protocol(root);grant::require_approved(root,protocol_hash(root));release(root,false);require(!fs::exists(root/"calibration-started"),"Calibration already started; no retry");Budget budget=read_budget(root/"baseline-started/budget.bin",protocol_hash(root));fs::create_directory(root/"calibration-started");cp::Lease lease((root/"physical-owner").string());const auto parents=load_parents(root);const auto initial=read_checkpoint(root/"policy-update-0.bin",protocol_hash(root),parents);
 try{disk_guard(root,environments);Data data;Minibatch b;nn::GpuMlp actor(actor_spec(),2*minibatch,1),critic(critic_spec(),minibatch,critic_seed);initialize_networks(initial,actor,critic);auto collected=collect(data,actor,critic,parents,root/"calibration-started/batch",budget,0,0,true,false,15);write_batch(root/"calibration-started/batch",collected,protocol_hash(root));batch_safety(collected,true);targets(data,b,root/"calibration-started/batch");evidence_guard(root);
 cp::Writer ready;ready.value(ready_magic);ready.value(version);ready.value(protocol_hash(root));for(const char* file:{"calibration-started/batch/meta.bin","calibration-started/batch/trace.bin","calibration-started/batch/gae.bin"})ready.value(file_hash(root/file));cp::write_atomic((root/"calibration-ready.bin").string(),ready.data);write_budget(root/"calibration-started/budget.bin",budget,protocol_hash(root));json(root/"calibration-result.json",result_json("calibration-ready",budget,0,0,0,0,0,Retention{},false));return 0;}
 catch(const std::exception& error){write_budget(root/"calibration-started/budget.bin",budget,protocol_hash(root));json(root/"calibration-result.json",result_json("calibration-stopped",budget,0,0,0,0,0,Retention{},false));std::cerr<<error.what()<<'\n';return 2;}}
int train(const fs::path& root){validate_protocol(root);grant::require_approved(root,protocol_hash(root));release(root,false);release(root,true);require(!fs::exists(root/"training-started"),"Training already started; no retry/resume/extension");Budget budget=read_budget(root/"calibration-started/budget.bin",protocol_hash(root));fs::create_directory(root/"training-started");cp::Lease lease((root/"physical-owner").string());const auto parents=load_parents(root);const auto initial=read_checkpoint(root/"policy-update-0.bin",protocol_hash(root),parents);
 nn::GpuMlp actor(actor_spec(),2*minibatch,1),critic(critic_spec(),minibatch,critic_seed);nn::GpuAdam actor_opt(actor_parameters,optimizer_config(true)),critic_opt(critic_parameters,optimizer_config(false));restore(initial,actor,critic,actor_opt,critic_opt);int completed=0,last_passes=0,withheld_passes=0;Retention retained;
 try{for(int update=1;update<=maximum_updates;++update){budget.guard();disk_guard(root,environments);const auto directory=root/"training-started"/("update-"+std::to_string(update));Data data;Minibatch batch;auto b=collect(data,actor,critic,parents,directory,budget,1,update,true,false,task::curriculum_limit(update));write_batch(directory,b,protocol_hash(root));batch_safety(b,true);targets(data,batch,directory);(void)optimize(data,batch,actor,critic,actor_opt,critic_opt,update,directory,budget);completed=update;save_checkpoint(root/("policy-update-"+std::to_string(update)+".bin"),protocol_hash(root),parents,update,actor,critic,actor_opt,critic_opt);
 if(update%4==0){disk_guard(root,22);Data evaluation(22);auto evaluated=collect(evaluation,actor,critic,parents,root/"training-started"/("assessment-"+std::to_string(update)),budget,3,update,false);write_batch(root/"training-started"/("assessment-"+std::to_string(update)),evaluated,protocol_hash(root));require(evaluated.fault==0,"Development physical fault");last_passes=score_evaluation(evaluated,root/"training-started"/("assessment-"+std::to_string(update))).passes;}
 evidence_guard(root);write_budget(root/"training-started/budget.bin",budget,protocol_hash(root));std::cout<<"update="<<update<<" actor_adam="<<actor_opt.steps()<<" critic_adam="<<critic_opt.steps()<<" latest_development="<<last_passes<<"/22 controls="<<budget.controls<<std::endl;}
 // Exactly actor32, no re-selection or further optimizer after final evidence.
 disk_guard(root,22);Data withheld(22);auto final=collect(withheld,actor,critic,parents,root/"withheld-turns",budget,4,32,false,true);write_batch(root/"withheld-turns",final,protocol_hash(root));require(final.fault==0,"Withheld physical fault");withheld_passes=score_evaluation(final,root/"withheld-turns").passes;retained=assess_retention(actor.get_params(),root/"final-retention",budget,true,parents.hold_gain);evidence_guard(root);
 const bool qualified=completed==32&&last_passes==22&&withheld_passes==22&&retention_passed(retained,true);write_budget(root/"training-started/budget.bin",budget,protocol_hash(root));json(root/"training-result.json",result_json("training-closed",budget,completed,actor_opt.steps(),critic_opt.steps(),last_passes,withheld_passes,retained,qualified));return 0;}
 catch(const std::exception& error){write_budget(root/"training-started/budget.bin",budget,protocol_hash(root));json(root/"training-result.json",result_json("training-stopped",budget,completed,actor_opt.steps(),critic_opt.steps(),last_passes,withheld_passes,retained,false));std::cerr<<error.what()<<'\n';return 2;}}
}
int main(int argc,char** argv){try{using namespace requested_turn_study_v1;if(argc==5&&std::string(argv[1])=="--prepare")return prepare(fs::absolute(argv[2]),fs::absolute(argv[3]),fs::absolute(argv[4]));
 if(argc==3){const auto root=fs::absolute(argv[2]);const std::string phase=argv[1];if(phase=="--preflight")return preflight(root);if(phase=="--baseline")return baseline(root);if(phase=="--calibrate")return calibrate(root);if(phase=="--train")return train(root);}
 std::cerr<<"Usage: requested_turn_ppo_v1 --prepare RUN PARENTS PROTOCOL | --preflight RUN | --baseline RUN | --calibrate RUN | --train RUN\n";return 1;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 2;}}
